	open fun add_lstep_sample(j: Int, dt: Double, dur: Double, rs: Double) {
		var u: Long = j.toLong()
		if ((this.stat_lstep_time!!.a!![u.toInt()] <= 0.0) || (dt < this.stat_lstep_min!!.a!![u.toInt()])) {
			this.stat_lstep_min!!.a!![u.toInt()] = dt
		}
		if (dt > this.stat_lstep_max!!.a!![u.toInt()]) {
			this.stat_lstep_max!!.a!![u.toInt()] = dt
		}
		this.stat_lstep_dt_time!!.a!![u.toInt()] += dt * dur
		this.stat_lstep_time!!.a!![u.toInt()] += dur
		this.stat_lstep_bin_time!!.a!![((u * LinkData.N_LSTEP_BINS.toLong()) + LinkData.lstep_bin(dt, rs).toLong()).toInt()] += dur
	}

