		(r!![9] as FN49?)!!.invoke(this.comments)
		(r!![9] as FN49?)!!.invoke(this.tags)
		(r!![2] as FN42?)!!.invoke(this.stat_flow_class)
		(r!![2] as FN42?)!!.invoke(this.stat_lstep_min)
		(r!![2] as FN42?)!!.invoke(this.stat_lstep_max)
		(r!![2] as FN42?)!!.invoke(this.stat_lstep_dt_time)
