		(r!![7] as FN47?)!!.invoke(this.stat_conv_steps)
		(r!![7] as FN47?)!!.invoke(this.stat_conv_total)
		this.stat_lstep_bin_time!!.reserve(un * LinkData.N_LSTEP_BINS.toLong())
	}

	open fun resize_loads(n_pollutants: Int) {
		this.stat_n_pollutants = n_pollutants
		if (n_pollutants > 0) {
			var total: Long = this.count().toLong() * n_pollutants.toLong()
			this.stat_total_load!!.assign_ul_T(total, 0.0)
		}
	}

	open fun resize_quality(n_pollutants: Int) {
		this.conc_n_pollutants = n_pollutants
		if (n_pollutants > 0) {
			var total: Long = this.count().toLong() * n_pollutants.toLong()
			this.conc!!.assign_ul_T(total, 0.0)
			this.conc_old!!.assign_ul_T(total, 0.0)
		}
	}

