	open fun save_hyd_state() {
		cpp.Algo.copy_IterT_IterT_IterT__D(this.flow!!.begin(), this.flow!!.end(), this.old_flow!!.begin())
		cpp.Algo.copy_IterT_IterT_IterT__D(this.depth!!.begin(), this.depth!!.end(), this.old_depth!!.begin())
		cpp.Algo.copy_IterT_IterT_IterT__D(this.volume!!.begin(), this.volume!!.end(), this.old_volume!!.begin())
	}

	open fun save_qual_state() {
		cpp.Algo.copy_IterT_IterT_IterT__D(this.conc!!.begin(), this.conc!!.end(), this.conc_old!!.begin())
	}

	open fun reset_state() {
		cpp.Algo.fill_IterT_IterT_T__D(this.flow!!.begin(), this.flow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.kw_inflow!!.begin(), this.kw_inflow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.depth!!.begin(), this.depth!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.volume!!.begin(), this.volume!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.froude!!.begin(), this.froude!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__B(this.flow_class!!.begin(), this.flow_class!!.end(), (0).toByte())
		cpp.Algo.fill_IterT_IterT_T__D(this.old_flow!!.begin(), this.old_flow!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.old_depth!!.begin(), this.old_depth!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.old_volume!!.begin(), this.old_volume!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.conc!!.begin(), this.conc!!.end(), 0.0)
		cpp.Algo.fill_IterT_IterT_T__D(this.conc_old!!.begin(), this.conc_old!!.end(), 0.0)
	}

	companion object {
		@JvmField var N_FLOW_CLASSES: Int = 7
		@JvmField var N_LSTEP_BINS: Int = 5
		@JvmStatic fun New_rLinkData(p: LinkData?): LinkData? {
			var o: LinkData? = LinkData(cpp.Raw.V)
			o!!.__init_rLinkData(p)
			return o
		}

		@JvmStatic fun New_mLinkData(p: LinkData?): LinkData? {
			var o: LinkData? = LinkData(cpp.Raw.V)
			o!!.__init_mLinkData(p)
			return o
		}

		@JvmStatic fun New(): LinkData? {
			var o: LinkData? = LinkData(cpp.Raw.V)
			o!!.__init_d()
			return o
		}

		@JvmStatic fun MoveNew(s: LinkData?): LinkData? {
			var o: LinkData? = LinkData(cpp.Raw.V)
			o!!.MoveFrom(s)
			return o
		}

		@JvmStatic fun lstep_bin(dt: Double, rs: Double): Int {
			var b: Int = 0
			var edge: Double = 0.5 * rs
			__L1@ while ((b < (LinkData.N_LSTEP_BINS - 1)) && (dt <= edge)) {
				b++
				edge *= 0.5
			}
			return b
		}

	}
}
